    info: `### Для чего используется
**Wells score для ТГВ (1997, mod. 2003)** — прикроватная клиническая оценка вероятности **тромбоза глубоких вен** до лабораторных/инструментальных исследований. Определяет нужно ли делать D-димер или идти сразу на УЗДС.

### Три- или двухуровневая модель
**Трёхуровневая (оригинал 1997)**:
| Баллы | Вероятность |
|---|---|
| ≤ 0 | Низкая (3 %) |
| 1–2 | Умеренная (17 %) |
| ≥ 3 | Высокая (53 %) |

**Двухуровневая (2003, современная)**:
| Баллы | Вероятность |
|---|---|
| < 2 | ТГВ маловероятен |
| ≥ 2 | ТГВ вероятен |

### Алгоритм (ACCP 2021, ESC 2019)
1. Wells ≥ 2 → **УЗДС вен ноги** (компрессионное)
   - Положительно → антикоагуляция
   - Отрицательно → повторить УЗДС через 5–7 дней (или добавить D-димер)
2. Wells < 2 → **D-димер** (высокочувствительный)
   - Отрицательный (< 500 нг/мл FEU, < возраст × 10 у > 50 лет) → ТГВ исключён
   - Положительный → УЗДС

### D-димер — age-adjusted cutoff (возраст-скорректированный)
У > 50 лет: порог = **возраст × 10 нг/мл** (FEU) или **возраст × 5** (DDU).
Повышает специфичность, сохраняя NPV ~ 100 %.

### Когда D-димер не работает
- Беременность (всегда повышен)
- Рак
- Постоперационный период (до 4 нед)
- ДВС
- Сепсис
- Возраст > 80 без коррекции
- Hospitalized patients

### Лечение подтверждённого ТГВ
**Выбор антикоагулянта (ACCP 2021)**:
| Ситуация | Препарат |
|---|---|
| Некомплицированный ТГВ | DOAC (апиксабан 10×2×7 дн → 5×2; ривароксабан 15×2×21 дн → 20×1) |
| Рак-ассоциированный ТГВ | DOAC или LMWH (эноксапарин 1 мг/кг × 2) |
| Беременность | LMWH |
| CrCl < 30 | LMWH или варфарин |
| Массивная ТЭЛА с шоком | Тромболизис + LMWH / UFH |

**Длительность** (ACCP):
- Провокированный (операция, иммобилизация) — 3 мес
- Непровокированный — 3+ мес (рассмотреть пожизненно)
- Рак — до излечения

### ТЭЛА сопутствующая
~ 50 % пациентов с проксимальным ТГВ имеют бессимптомную ТЭЛА. При диагнозе ТГВ — опционально КТ-ангио если есть лёгочные симптомы.

### Ограничения Wells для ТГВ
- Субъективная оценка "альтернативного диагноза" (−2 балла)
- Низкая специфичность у пожилых, стационарных, онкологических пациентов
- Не валидизирован при изолированном ТГВ верхних конечностей — используйте **Constans score**

### Дополнительные клинические предикторы (не в Wells)
- Возраст > 60
- Беременность / послеродовой период до 6 нед
- Эстрогены (КОК, ЗГТ)
- Тромбофилия (Leiden, протромбин G20210A, антифосфолипидный)
- Длительный перелёт > 4 ч`,
