    reference: 'Nathan RA. JACI 2004. Asthma Control Test (ACT) ≥ 12 лет.',
    info: `### Что измеряет
**Asthma Control Test (ACT)** — самозаполняемый опросник для оценки контроля бронхиальной астмы у пациентов **≥ 12 лет** за последние **4 недели**. Для детей 4–11 лет используется **C-ACT** (7 вопросов).

### Интерпретация
| Сумма | Контроль |
|---|---|
| 25 | Полный контроль |
| 20–24 | Хороший / достаточный |
| < 20 | Недостаточный — пересмотр терапии |
| ≤ 15 | Очень плохой — срочное усиление и оценка приверженности |

Минимально клинически значимое изменение (MCID) — **3 балла**.

### Связь с GINA
ACT — комплементарен GINA-критериям:
- **Хороший контроль**: дневные симптомы ≤ 2/нед, нет ночных, потребности в SABA ≤ 2/нед, нет ограничений активности
- **Частичный**: 1–2 признака
- **Не контролируется**: 3–4 признака

### Шаги терапии (GINA 2024, взрослые)
| Шаг | Поддерживающая |
|---|---|
| 1–2 | Низкие дозы ИГКС-формотерол по требованию (MART concept, AIR) |
| 3 | Низкие дозы ИГКС-LABA ежедневно + по требованию ИГКС-формотерол |
| 4 | Средние дозы ИГКС-LABA |
| 5 | Высокие ИГКС-LABA + биологическая терапия (омализумаб, меполизумаб, дупилумаб, тезепелумаб) |

### Биомаркеры для биологической терапии
- **Эозинофилы крови** ≥ 300/мкл и/или **FeNO** ≥ 25 ppb → Type-2 high astma
- IgE-обусловленная аллергия → омализумаб

### Ограничения
- Не оценивает функцию лёгких — параллельно делайте ОФВ₁ и пиковую скорость
- Зависит от честности пациента
- Период оценки 4 нед — может пропустить недавнее ухудшение`,
